  const ship = quote({ method: shippingMethod || 'standard', weightGrams: 500 * cart.items.length });
  const total = goods + (ship || 0);
  const order = makeOrder({ id: uuid(), userId, items: cart.items, total });
  save(order);
  clear(userId);
  return { ok: true, order };
}
